/** Clamped linear interpolation of `v` between `vLo..vHi` as `w` runs `wLo..wHi`. */
function clampLerp(w: number, wLo: number, wHi: number, vLo: number, vHi: number): number {
  if (w <= wLo) return vLo
  if (w >= wHi) return vHi
  return vLo + ((w - wLo) / (wHi - wLo)) * (vHi - vLo)
}

